/**
 * Group TNA models — build and manage per-group transition networks.
 * Port of Python tna/group.py
 */
import { buildModel } from './model.js';
import { ATTENTION_DEFAULT_BETA } from './transitions.js';
import type { TNA, GroupTNA, SequenceData, BuildModelOptions, ModelType } from './types.js';

/** Check if an object is a GroupTNA (duck typing). */
export function isGroupTNA(x: unknown): x is GroupTNA {
  return typeof x === 'object' && x !== null && 'models' in x;
}

/**
 * Check if a TNA is an HTNA (has the actor partition populated).
 * HTNA is a TNA with the same shape plus a `partition: string[]` field
 * tagging each node with its actor group — no separate type, no separate factory.
 */
export function isHtna(x: unknown): x is TNA & { partition: string[]; actorLevels: string[] } {
  return (
    typeof x === 'object' && x !== null &&
    'weights' in x && 'labels' in x &&
    Array.isArray((x as TNA).partition) &&
    (x as TNA).partition!.length === (x as TNA).labels.length
  );
}

/** Create a GroupTNA from a models record. */
export function createGroupTNA(models: Record<string, TNA>): GroupTNA {
  return { models };
}

/** Get group names. */
export function groupNames(g: GroupTNA): string[] {
  return Object.keys(g.models);
}

/** Iterate over groups. */
export function groupEntries(g: GroupTNA): [string, TNA][] {
  return Object.entries(g.models);
}

/** Apply a function to each group model. */
export function groupApply<T>(g: GroupTNA, fn: (model: TNA, name: string) => T): Record<string, T> {
  const result: Record<string, T> = {};
  for (const [name, model] of Object.entries(g.models)) {
    result[name] = fn(model, name);
  }
  return result;
}

/** Rename groups. */
export function renameGroups(g: GroupTNA, newNames: string[]): GroupTNA {
  const oldNames = Object.keys(g.models);
  if (newNames.length !== oldNames.length) {
    throw new Error(`Expected ${oldNames.length} names, got ${newNames.length}`);
  }
  const models: Record<string, TNA> = {};
  for (let i = 0; i < oldNames.length; i++) {
    models[newNames[i]!] = g.models[oldNames[i]!]!;
  }
  return { models };
}

/**
 * Build one TNA model per group.
 *
 * @param data - Sequence data for all groups
 * @param groups - Group label for each sequence (same length as data)
 * @param options - Build options (type, scaling, labels, etc.)
 */
function buildGroupModels(
  data: SequenceData,
  groups: string[],
  options?: BuildModelOptions & { type?: ModelType },
): GroupTNA {
  if (data.length !== groups.length) {
    throw new Error(`Data length ${data.length} doesn't match groups length ${groups.length}`);
  }

  // Detect shared labels across all groups
  let labels = options?.labels;
  if (!labels) {
    const stateSet = new Set<string>();
    for (const row of data) {
      for (const val of row) {
        if (val !== null && val !== undefined && val !== '') {
          stateSet.add(val);
        }
      }
    }
    labels = Array.from(stateSet).sort();
  }

  // Get unique groups in order of appearance
  const uniqueGroups: string[] = [];
  const seen = new Set<string>();
  for (const g of groups) {
    if (!seen.has(g)) {
      uniqueGroups.push(g);
      seen.add(g);
    }
  }

  // Build one model per group WITHOUT scaling (scaling is applied globally)
  const scalingOpt = options?.scaling ?? null;
  const optsNoScaling = { ...options, scaling: undefined, labels };
  const models: Record<string, TNA> = {};
  for (const grp of uniqueGroups) {
    const grpData: SequenceData = [];
    for (let i = 0; i < data.length; i++) {
      if (groups[i] === grp) {
        grpData.push(data[i]!);
      }
    }
    models[grp] = buildModel(grpData, optsNoScaling);
  }

  // Apply scaling GLOBALLY across all groups (matches R's scale_weights_global)
  if (scalingOpt) {
    const type = options?.type ?? 'relative';
    const grpNames = Object.keys(models);
    const n = models[grpNames[0]!]!.weights.rows;

    // R's scale_weights_global re-row-normalizes for relative type.
    // Note: R's `w[!pos, ] <- NA` is a no-op (logical NOT of integer vector = FALSE),
    // so dead-end rows keep their zero values and get ranked alongside other zeros.
    if (type === 'relative') {
      for (const name of grpNames) {
        const w = models[name]!.weights;
        for (let i = 0; i < n; i++) {
          let rs = 0;
          for (let j = 0; j < n; j++) rs += w.get(i, j);
          if (rs > 0) {
            for (let j = 0; j < n; j++) w.set(i, j, w.get(i, j) / rs);
          }
        }
      }
    }

    // Flatten column-major (matching R's as.vector/unlist on matrices)
    const allVals: number[] = [];
    for (const name of grpNames) {
      const w = models[name]!.weights;
      for (let j = 0; j < n; j++) {
        for (let i = 0; i < n; i++) {
          allVals.push(w.get(i, j));
        }
      }
    }

    let scaled: number[];
    if (scalingOpt === 'rank') {
      // Global rank (average ties) matching R's rank(ties.method="average")
      const indexed = allVals.map((v, i) => ({ v, i }));
      indexed.sort((a, b) => a.v - b.v);
      scaled = new Array(allVals.length);
      let idx = 0;
      while (idx < indexed.length) {
        let end = idx;
        while (end < indexed.length && indexed[end]!.v === indexed[idx]!.v) end++;
        const avgRank = (idx + 1 + end) / 2;
        for (let k = idx; k < end; k++) scaled[indexed[k]!.i] = avgRank;
        idx = end;
      }
    } else if (scalingOpt === 'minmax') {
      const min = Math.min(...allVals);
      const max = Math.max(...allVals);
      const range = max - min || 1;
      scaled = allVals.map(v => (v - min) / range);
    } else if (scalingOpt === 'max') {
      const max = Math.max(...allVals);
      scaled = max === 0 ? [...allVals] : allVals.map(v => v / max);
    } else {
      scaled = allVals;
    }

    // Write back (column-major to match flattening order)
    let offset = 0;
    for (const name of grpNames) {
      const w = models[name]!.weights;
      for (let j = 0; j < n; j++) {
        for (let i = 0; i < n; i++) {
          w.set(i, j, scaled[offset++]!);
        }
      }
    }
  }

  return { models };
}

/** Build grouped relative transition probability models. */
export function groupTna(
  data: SequenceData,
  groups: string[],
  options?: Omit<BuildModelOptions, 'type' | 'params'>,
): GroupTNA {
  return buildGroupModels(data, groups, { ...options, type: 'relative' });
}

/** Build grouped frequency-based transition models. */
export function groupFtna(
  data: SequenceData,
  groups: string[],
  options?: Omit<BuildModelOptions, 'type' | 'params'>,
): GroupTNA {
  return buildGroupModels(data, groups, { ...options, type: 'frequency' });
}

/** Build grouped co-occurrence transition models. */
export function groupCtna(
  data: SequenceData,
  groups: string[],
  options?: Omit<BuildModelOptions, 'type' | 'params'>,
): GroupTNA {
  return buildGroupModels(data, groups, { ...options, type: 'co-occurrence' });
}

/** Build grouped attention-weighted transition models. */
export function groupAtna(
  data: SequenceData,
  groups: string[],
  options?: Omit<BuildModelOptions, 'type'> & { beta?: number },
): GroupTNA {
  return buildGroupModels(data, groups, {
    ...options,
    type: 'attention',
    params: { beta: options?.beta ?? ATTENTION_DEFAULT_BETA },
  });
}
